<script setup>
import {ref} from 'vue'
import {session} from '../session'
import {useData} from '../data'
import {t} from '../i18n'
import {formatDate} from '../api'
import AnalysisReview from './AnalysisReview.vue'
const props=defineProps({call:Object,role:{default:'admin'}}),emit=defineEmits(['close']),review=ref(false),base=()=>'/api/v1/calls/'+props.call.id
const speech=useData(()=>base()+'/speech-turns'),analysis=useData(()=>base()+'/analysis'),recordings=useData(()=>base()+'/recordings'),metrics=useData(()=>base()+'/metrics'),events=useData(()=>base()+'/events?page=1&size=100')
</script><template><el-drawer :model-value="true" :title="t('events')+' · '+call.phone" size="720px" @close="emit('close')"><el-descriptions :column="1" border><el-descriptions-item label="ID">{{call.id}}</el-descriptions-item><el-descriptions-item :label="t('status')">{{t(call.status)}}</el-descriptions-item><el-descriptions-item :label="t('mode')">{{t(call.mode)}}</el-descriptions-item></el-descriptions><el-tabs><el-tab-pane label="结构化转写"><div class="speech-list" v-loading="speech.loading.value"><div v-for="item in speech.data.value||[]" :key="item.id" class="speech-turn" :class="item.speaker_role"><el-tag>{{item.speaker_role}} · {{item.is_final?'最终':'临时'}}</el-tag><span class="hint"> 置信度 {{item.confidence==null?'-':Math.round(item.confidence*100)+'%'}}</span><p>{{item.transcript||'（空转写）'}}</p></div><el-empty v-if="!speech.data.value?.length" :description="t('empty')"/></div></el-tab-pane><el-tab-pane :label="t('resultsAndQa')"><template v-if="analysis.data.value"><el-descriptions :column="1" border><el-descriptions-item v-for="[key,label] in [['result_code','callResult'],['intent','intent'],['sentiment','sentiment'],['qa_score','qaScore'],['qa_flags_json','qaFlags'],['review_state','reviewState'],['summary','summary']]" :key="key" :label="t(label)">{{analysis.data.value[key]}}</el-descriptions-item></el-descriptions><el-tag v-if="analysis.data.value.needs_review" type="warning">有新证据，待复核</el-tag><el-button v-if="role==='admin'||session.user?.is_supervisor" type="primary" @click="review=true">{{t('correctAnalysis')}}</el-button></template><el-empty v-else :description="analysis.loading.value?t('loading'):t('empty')"/></el-tab-pane><el-tab-pane label="录音资产"><div v-for="item in recordings.data.value||[]" :key="item.id" class="record-card"><div class="actions"><el-tag>{{item.state}}</el-tag><el-tag>{{item.attempt?'第 '+item.attempt+' 轮':'历史轮次未知'}}</el-tag><span>{{item.media_format||'unknown'}} · {{item.duration_sec==null?'-':item.duration_sec+'s'}}</span></div><p>{{item.storage_uri||item.provider_url}}</p></div><el-empty v-if="!recordings.data.value?.length" :description="t('empty')"/></el-tab-pane><el-tab-pane label="阶段指标"><DataGrid :rows="metrics.data.value" :columns="[{key:'stage',label:'阶段'},{key:'duration_ms',label:'耗时',render:v=>v==null?'-':v+' ms'},{key:'success',label:'结果'},{key:'error_code',label:'错误码'}]"/></el-tab-pane><el-tab-pane :label="t('events')"><div v-for="event in events.data.value||[]" :key="event.id" class="record-card"><el-tag>{{event.event_type}}</el-tag> {{formatDate(event.created_at)}}<JsonView :value="event.payload"/></div><el-empty v-if="!events.data.value?.length" :description="t('empty')"/></el-tab-pane></el-tabs></el-drawer><AnalysisReview v-if="review&&analysis.data.value" :analysis="analysis.data.value" :call-id="call.id" @close="review=false" @saved="analysis.load"/></template>
